import { useEffect, useMemo, useRef, useState } from 'react'
import { AlertTriangle, BriefcaseBusiness, Building2, Check, ChevronRight, CircleUserRound, Download, ExternalLink, FileJson, FileText, Files, Globe2, LayoutDashboard, ListChecks, LoaderCircle, LockKeyhole, LogOut, MapPin, Play, Plus, RefreshCw, Save, ShieldCheck, Sparkles, Target, Trash2, UploadCloud, UserPlus, WandSparkles, X } from 'lucide-react'
import { API, ApiError, api } from './api'
import type { ApplicationQueueItem, ApplicationWorkflowState, BrowserSnapshot, CandidateProfile, Conflict, Education, Evidence, ExecutionResult, Experience, FieldComparison, FillAction, FormPlan, JobRecommendation, JobVerification, LiveJobStatus, NativeResumeImportResult, PageField, PreSubmitCheck, Project, RecommendationBatch, ResumeProfile, ResumeRecord, UserAccount } from './types'

type Page='overview'|'jobs'|'profile'|'resumes'|'review'|'demo'
const emptyEducation:Education={school:'',college:'',degree:'',major:'',location:'',start_date:'',end_date:'',gpa:'',ranking:'',courses:[],description:'',current:false}
const emptyExperience:Experience={organization:'',department:'',role:'',employment_type:'',location:'',start_date:'',end_date:'',current:false,description:'',achievements:[],technologies:[]}
const emptyProject:Project={name:'',role:'',start_date:'',end_date:'',background:'',description:'',achievements:[],technologies:[],project_url:'',github_url:''}
const labels:Record<string,string>={name:'姓名',english_name:'英文姓名',gender:'性别',birth_date:'出生日期',age:'年龄',phone:'手机号',email:'邮箱',country_region:'国家/地区',qq:'QQ',wechat:'微信',location:'当前城市',hometown:'籍贯',website:'个人网站',github:'GitHub',linkedin:'LinkedIn',target_role:'目标岗位',available_date:'可入职时间',internship_duration:'实习时长',days_per_week:'每周天数',expected_salary:'期望薪资',remote_preference:'远程偏好',summary:'个人简介',education:'教育经历',internships:'实习经历',projects:'项目经历',skills:'技能'}

export default function App(){
  const [user,setUser]=useState<UserAccount|null|undefined>(undefined)
  const [page,setPage]=useState<Page>('overview'); const [profile,setProfile]=useState<CandidateProfile|null>(null)
  const [resumes,setResumes]=useState<ResumeRecord[]>([]); const [conflicts,setConflicts]=useState<Conflict[]>([])
  const [selected,setSelected]=useState(''); const [rawText,setRawText]=useState(''); const [busy,setBusy]=useState(false); const [notice,setNotice]=useState('')
  const [launchJob,setLaunchJob]=useState<{recommendation:JobRecommendation;resumeId:string}|null>(null)
  const fileInput=useRef<HTMLInputElement>(null)
  const reload=async()=>{try{const [p,r,c]=await Promise.all([api.profile(),api.list(),api.conflicts()]);setProfile(p);setResumes(r);setConflicts(c);if(!selected&&r[0])setSelected(r[0].id)}catch(e){if(e instanceof ApiError&&e.status===401)setUser(null);else setNotice(message(e))}}
  useEffect(()=>{api.me().then(setUser).catch(()=>setUser(null))},[])
  useEffect(()=>{if(user)reload()},[user?.id])
  useEffect(()=>{if(page!=='review'||!selected)return;let active=true;setRawText('');api.text(selected).then(data=>{if(active)setRawText(data.text)}).catch(e=>{if(active)setNotice(message(e))});return()=>{active=false}},[page,selected])
  const active=resumes.find(r=>r.id===selected)??null
  const upload=async(file?:File)=>{if(!file)return;setBusy(true);setNotice('Agent 正在读取、拆分并合并资料…');try{const item=await api.upload(file);await reload();setSelected(item.id);setPage('review');setNotice('解析完成。请检查识别证据和冲突。')}catch(e){if(e instanceof ApiError&&typeof e.detail==='object'&&e.detail&&'resume_id' in e.detail){await reload();setSelected(String((e.detail as {resume_id:unknown}).resume_id));setPage('resumes')}setNotice(message(e))}finally{setBusy(false);if(fileInput.current)fileInput.current.value=''}}
  const openReview=(id:string)=>{setSelected(id);setPage('review')}
  const updateResumeLocal=(item:ResumeRecord)=>setResumes(all=>all.map(r=>r.id===item.id?item:r))
  const nav=[['overview','总览',LayoutDashboard],['jobs','岗位推荐',Target],['profile','主档案',CircleUserRound],['resumes','简历资料库',Files],['review','待确认',AlertTriangle],['demo','投递工作台',Globe2]] as const
  const logout=async()=>{try{await api.logout()}catch{}setUser(null);setProfile(null);setResumes([]);setConflicts([]);setSelected('');setRawText('');setLaunchJob(null);setPage('overview');setNotice('')}
  if(user===undefined)return <div className="auth-loading"><LoaderCircle className="spin" size={28}/><span>正在恢复登录状态…</span></div>
  if(!user)return <AuthPage onAuthenticated={setUser}/>
  return <div className="shell"><aside><div className="brand"><span><BriefcaseBusiness size={20}/></span><div><strong>职达 Zhida</strong><small>求职资料 Agent</small></div></div>
    <button className="primary full" onClick={()=>fileInput.current?.click()} disabled={busy}><Plus size={17}/>上传新简历</button><input ref={fileInput} hidden type="file" accept=".pdf,.docx,.txt" onChange={e=>upload(e.target.files?.[0])}/>
    <nav>{nav.map(([key,label,Icon])=><button key={key} className={page===key?'active':''} onClick={()=>setPage(key)}><Icon size={18}/>{label}{key==='review'&&<b>{conflicts.length+resumes.flatMap(r=>r.evidence).filter(e=>e.status==='pending_review').length}</b>}</button>)}</nav>
    <div className="privacy"><ShieldCheck size={17}/><div><strong>受控模型传输</strong><small>只在解析与匹配时发送</small></div></div><div className={`account-chip ${user.is_local?'local':''}`}><span>{user.is_local?'本':(user.display_name||user.email)[0].toUpperCase()}</span><div><strong>{user.is_local?'本机免登录':user.display_name||'职达用户'}</strong><small>{user.is_local?'数据保存在当前电脑':user.email}</small></div>{!user.is_local&&<button title="退出登录" onClick={logout}><LogOut size={15}/></button>}</div></aside>
    <main><Top page={page}/>{notice&&<div className="notice">{notice}<button onClick={()=>setNotice('')}>×</button></div>}
      {page==='overview'&&profile&&<Overview profile={profile} resumes={resumes} conflicts={conflicts} go={setPage}/>}
      {page==='jobs'&&profile&&<JobRecommendations profile={profile} resumes={resumes} notify={setNotice} onApply={(job,resumeId)=>{setLaunchJob({recommendation:job,resumeId});setPage('demo');setNotice(`已选择 ${job.job.company} · ${job.job.title}，岗位链接已自动带入投递工作台。`)}}/>}
      {page==='profile'&&profile&&<ProfileEditor profile={profile} onSave={async p=>{setBusy(true);try{setProfile(await api.saveProfile(p));setNotice('主档案已保存。')}catch(e){setNotice(message(e))}finally{setBusy(false)}}}/>}
      {page==='resumes'&&<ResumeLibrary resumes={resumes} busy={busy} upload={()=>fileInput.current?.click()} onReview={openReview} onRefresh={async r=>{setBusy(true);try{updateResumeLocal(await api.reparse(r.id));await reload();setNotice('重新解析完成。')}catch(e){await reload();setNotice(message(e))}finally{setBusy(false)}}} onDefault={async r=>{updateResumeLocal(await api.saveResume(r.id,{is_default:true}));await reload()}} onDelete={async r=>{if(!confirm(`确定删除“${r.label}”及其原始文件吗？`))return;await api.deleteResume(r.id);await reload();setNotice('简历及原始文件已删除。')}}/>}
      {page==='review'&&<ReviewWorkspace resumes={resumes} active={active} conflicts={conflicts} rawText={rawText} select={openReview} notify={setNotice} onReviewed={async item=>{updateResumeLocal(item);setProfile(await api.profile())}} onResolved={async(id,choice,custom)=>{await api.resolve(id,choice,custom);await reload();setNotice('冲突已处理，主档案已更新。')}}/>}
      {page==='demo'&&<BrowserDemo profile={profile} resumes={resumes} notify={setNotice} onProfileUpdate={setProfile} initialJob={launchJob?.recommendation??null} initialResumeId={launchJob?.resumeId??''}/>}
    </main></div>
}

function AuthPage({onAuthenticated}:{onAuthenticated:(user:UserAccount)=>void}){
  const [mode,setMode]=useState<'login'|'register'>('login');const [displayName,setDisplayName]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [confirmPassword,setConfirmPassword]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  const switchMode=(next:'login'|'register')=>{setMode(next);setError('');setPassword('');setConfirmPassword('')}
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');if(mode==='register'&&password!==confirmPassword){setError('两次输入的密码不一致');return}setBusy(true);try{const session=mode==='register'?await api.register(email,password,displayName):await api.login(email,password);onAuthenticated(session.user)}catch(err){setError(message(err))}finally{setBusy(false)}}
  return <main className="auth-shell"><section className="auth-brand"><span><BriefcaseBusiness size={27}/></span><strong>职达 Zhida</strong><small>让每一份求职资料都有清晰归属</small><div><ShieldCheck size={18}/><p><b>账号级资料隔离</b><br/>密码只保存安全哈希，简历和投递清单按用户分开。</p></div></section><section className="auth-card"><div className="auth-tabs"><button className={mode==='login'?'active':''} onClick={()=>switchMode('login')}>登录</button><button className={mode==='register'?'active':''} onClick={()=>switchMode('register')}>创建账号</button></div><div className="auth-heading"><span>{mode==='login'?<LockKeyhole size={19}/>:<UserPlus size={19}/>}</span><div><h1>{mode==='login'?'欢迎回来':'创建你的职达账号'}</h1><p>{mode==='login'?'继续管理简历和投递任务':'第一位注册用户会自动接管当前本地资料'}</p></div></div><form onSubmit={submit}>{mode==='register'&&<label><span>显示名称</span><input autoComplete="name" value={displayName} onChange={e=>setDisplayName(e.target.value)} placeholder="例如：李春博"/></label>}<label><span>邮箱账号</span><input type="email" autoComplete="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com"/></label><label><span>密码</span><input type="password" autoComplete={mode==='login'?'current-password':'new-password'} required minLength={8} value={password} onChange={e=>setPassword(e.target.value)} placeholder="至少 8 位，包含两类字符"/></label>{mode==='register'&&<label><span>确认密码</span><input type="password" autoComplete="new-password" required minLength={8} value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} placeholder="再次输入密码"/></label>}{error&&<div className="auth-error"><AlertTriangle size={15}/>{error}</div>}<button className="primary auth-submit" disabled={busy}>{busy?<LoaderCircle className="spin" size={17}/>:mode==='login'?<LockKeyhole size={17}/>:<UserPlus size={17}/>} {busy?'请稍候':mode==='login'?'登录':'创建账号并进入'}</button></form><footer>本地开发版使用 HttpOnly 会话 Cookie；部署时请开启 HTTPS。</footer></section></main>
}

function Top({page}:{page:Page}){const copy={overview:['候选人资料总览','一次维护，反复用于之后的每次申请。'],jobs:['推荐投递清单','根据已确认简历生成可解释推荐，选中后直接进入投递流程。'],profile:['候选人主档案','这里是你的事实来源，Agent 不会擅自覆盖已确认信息。'],resumes:['简历资料库','管理不同语言、岗位方向和版本的简历。'],review:['识别结果检查','对照原文确认 Agent 拆分的字段，并处理资料冲突。'],demo:['招聘网站投递工作台','让 Agent 理解表单，由 Playwright 安全执行，永不自动提交。']}[page];return <header><div><p className="eyebrow">ZHIDA / PROFILE WORKSPACE</p><h1>{copy[0]}</h1><p>{copy[1]}</p></div><a className="export" href={`${API}/export`} target="_blank" rel="noreferrer"><FileJson size={17}/>导出 JSON</a></header>}

function Overview({profile,resumes,conflicts,go}:{profile:CandidateProfile;resumes:ResumeRecord[];conflicts:Conflict[];go:(p:Page)=>void}){
  const pending=resumes.flatMap(r=>r.evidence).filter(e=>e.status==='pending_review').length
  const fields=[profile.name,profile.phone,profile.email,profile.location,profile.target_role,profile.summary,profile.education.length,profile.internships.length,profile.projects.length,profile.skills.length]
  const complete=Math.round(fields.filter(Boolean).length/fields.length*100)
  return <><section className="metric-grid"><Metric label="资料完整度" value={`${complete}%`} note="继续补充可提升投递覆盖" tone="green"/><Metric label="简历版本" value={String(resumes.length)} note={resumes.some(r=>r.is_default)?'已设置默认版本':'还没有默认简历'}/><Metric label="待确认字段" value={String(pending)} note="确认后成为可信资料"/><Metric label="信息冲突" value={String(conflicts.length)} note={conflicts.length?'需要你做最终选择':'目前没有冲突'} tone={conflicts.length?'amber':'green'}/></section>
    <section className="overview-grid"><div className="card profile-hero"><div className="avatar">{profile.name?.[0]||'职'}</div><div><p>候选人主档案</p><h2>{profile.name||'尚未填写姓名'}</h2><span>{profile.target_role||'添加目标岗位'} · {profile.location||'添加当前城市'}</span></div><button onClick={()=>go('profile')}>编辑档案<ChevronRight size={16}/></button></div>
    <div className="card next-step"><Sparkles size={22}/><div><h3>下一步建议</h3><p>{pending?`还有 ${pending} 个识别字段等待确认。`:resumes.length?'主档案已经可以用于生成推荐投递清单。':'上传一份简历，Agent 会自动拆分并生成推荐。'}</p></div><button onClick={()=>go(pending?'review':resumes.length?'jobs':'resumes')}>{!pending&&resumes.length?'查看推荐':'开始处理'}</button></div></section>
    <section className="card"><SectionTitle n="资料" title="经历素材概览" sub="主档案中的可复用事实"/><div className="fact-row"><Fact n={profile.education.length} label="教育经历"/><Fact n={profile.internships.length} label="实习经历"/><Fact n={profile.projects.length} label="项目经历"/><Fact n={profile.skills.length} label="技能关键词"/></div></section></>}
function Metric({label,value,note,tone=''}:{label:string;value:string;note:string;tone?:string}){return <div className={`metric ${tone}`}><span>{label}</span><strong>{value}</strong><small>{note}</small></div>}
function Fact({n,label}:{n:number;label:string}){return <div><strong>{n}</strong><span>{label}</span></div>}

function JobRecommendations({profile,resumes,notify,onApply}:{profile:CandidateProfile;resumes:ResumeRecord[];notify:(v:string)=>void;onApply:(job:JobRecommendation,resumeId:string)=>void}){
  const [batch,setBatch]=useState<RecommendationBatch|null>(null);const [queue,setQueue]=useState<ApplicationQueueItem[]>([]);const [selectedJobs,setSelectedJobs]=useState<Set<string>>(new Set());const [company,setCompany]=useState('全部公司');const [location,setLocation]=useState('');const [selectedResume,setSelectedResume]=useState('');const [busy,setBusy]=useState('')
  const load=async(nextLocation=location)=>{setBusy('loading');try{const [nextBatch,nextQueue]=await Promise.all([api.recommendations(nextLocation),api.jobQueue()]);setBatch(nextBatch);setQueue(nextQueue)}catch(e){notify(message(e))}finally{setBusy('')}}
  useEffect(()=>{load()},[profile.updated_at])
  useEffect(()=>{if(!selectedResume){const preferred=resumes.find(item=>item.is_default)??resumes[0];if(preferred)setSelectedResume(preferred.id)}},[resumes,selectedResume])
  const companies=useMemo(()=>['全部公司',...Array.from(new Set(batch?.jobs.map(item=>item.job.company)??[]))],[batch])
  const visible=useMemo(()=>batch?.jobs.filter(item=>company==='全部公司'||item.job.company===company)??[],[batch,company])
  const queuedIds=useMemo(()=>new Set(queue.map(item=>item.job_id)),[queue])
  const profileGap=!profile.target_role&&!profile.skills.length?'目标岗位和技能':!profile.target_role?'目标岗位':'技能'
  const toggle=(id:string)=>setSelectedJobs(current=>{const next=new Set(current);if(next.has(id))next.delete(id);else next.add(id);return next})
  const changeLocation=(value:string)=>{setLocation(value);setCompany('全部公司');setSelectedJobs(new Set());void load(value)}
  const add=async(ids:string[])=>{if(!ids.length)return;setBusy('queue');try{setQueue(await api.queueJobs(ids,selectedResume));setSelectedJobs(new Set());notify(`已将 ${ids.length} 个岗位加入候选清单；开始投递前会重新核验。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const verify=async(item:JobRecommendation):Promise<JobVerification|null>=>{setBusy(`verify:${item.job.id}`);try{const result=await api.verifyJob(item.job.id);setBatch(await api.recommendations(location));notify(`${item.job.company} · ${item.job.title}：${result.message}`);return result}catch(e){notify(message(e));return null}finally{setBusy('')}}
  const begin=async(item:JobRecommendation,resumeId=selectedResume)=>{setBusy(item.job.id);try{const verification=await api.verifyJob(item.job.id);const refreshed=await api.recommendations(location);setBatch(refreshed);const current=refreshed.jobs.find(candidate=>candidate.job.id===item.job.id)??item;if(['closed','mismatch','unreachable'].includes(verification.status)){notify(`已停止：${verification.message}`);return}if(current.formal_queue_eligible)setQueue(await api.queueJobs([item.job.id],resumeId));else notify(verification.status==='manual_gate'?'静态官网核验证据不足，即将先在 Chrome 中只读核验，不会直接填写或提交。':`官网可以访问，但${current.gate_reasons.join('、')}；本次进入人工核实流程，不计入正式投递队列。`);onApply(current,resumeId)}catch(e){notify(message(e))}finally{setBusy('')}}
  const remove=async(id:string)=>{setBusy(id);try{await api.removeQueuedJob(id);setQueue(current=>current.filter(item=>item.id!==id));notify('已从投递清单移除。')}catch(e){notify(message(e))}finally{setBusy('')}}
  if(!batch&&busy==='loading')return <section className="card recommendation-loading"><LoaderCircle className="spin" size={24}/><span>正在根据主档案计算岗位匹配度…</span></section>
  return <div className="stack jobs-workspace"><section className="card recommendation-hero"><div><span className="demo-icon"><Target size={22}/></span><div><h2>简历驱动的岗位推荐</h2><p>{batch?.profile_summary||'等待读取主档案'} · 本地可解释评分，不依赖当前故障中的模型 API</p></div></div><div className="recommendation-stats"><strong>{batch?.jobs.length??0}</strong><span>个候选岗位</span><small>{batch?.engine}</small></div></section>
    {(!profile.target_role||!profile.skills.length)&&<div className="profile-warning"><AlertTriangle size={17}/><span><strong>推荐依据还不完整</strong><small>补充{profileGap}后，匹配结果会更准确。</small></span></div>}
    <section className="card"><div className="recommendation-toolbar"><div><SectionTitle n="01" title="推荐岗位" sub="先选工作地点，再按公司筛选；开始投递前会对官网做一次实时核验"/></div><div className="recommendation-filters"><label><span>工作地点</span><select aria-label="工作地点" value={location} disabled={!!busy} onChange={e=>changeLocation(e.target.value)}><option value="">全部地点（按主档案排序）</option>{batch?.available_locations.map(item=><option value={item} key={item}>{item}</option>)}</select></label><label><span>公司</span><select aria-label="公司" value={company} onChange={e=>setCompany(e.target.value)}>{companies.map(item=><option key={item}>{item}</option>)}</select></label><button className="secondary" disabled={!!busy} onClick={()=>load()}><RefreshCw className={busy==='loading'?'spin':''} size={15}/>重新匹配</button></div></div>
      <div className="batch-bar"><label><input type="checkbox" checked={Boolean(visible.length)&&visible.every(item=>selectedJobs.has(item.job.id))} onChange={e=>setSelectedJobs(e.target.checked?new Set(visible.map(item=>item.job.id)):new Set())}/>选择当前结果</label><span>已选 {selectedJobs.size} 个</span><label className="queue-resume"><span>投递简历</span><select value={selectedResume} onChange={e=>setSelectedResume(e.target.value)}><option value="">暂不指定</option>{resumes.map(item=><option value={item.id} key={item.id}>{item.label}{item.is_default?' · 默认':''}</option>)}</select></label><button className="primary" disabled={!selectedJobs.size||!!busy} onClick={()=>add([...selectedJobs])}><ListChecks size={16}/>加入候选清单</button></div>
      <div className="job-grid">{visible.map(item=><article className={`job-card ${selectedJobs.has(item.job.id)?'selected':''}`} key={item.job.id}><div className="job-card-top"><label className="job-check"><input aria-label={`选择 ${item.job.company} ${item.job.title}`} type="checkbox" checked={selectedJobs.has(item.job.id)} onChange={()=>toggle(item.job.id)}/></label><div className="company-mark"><Building2 size={20}/></div><div className="job-title"><span>{item.job.company} · {item.job.recruitment_type}</span><h3>{item.job.title}</h3><p><MapPin size={12}/>{item.job.locations.join(' / ')}{item.job.job_code&&` · ${item.job.job_code}`}</p></div><div className={`score ${item.match_score>=75?'high':item.match_score>=60?'medium':'low'}`}><strong>{item.match_score}</strong><span>匹配分</span></div></div><p className="job-description">{item.job.description}</p><div className="match-columns"><div><span>已命中</span><div className="skill-tags matched">{item.matched_skills.length?item.matched_skills.map(skill=><b key={skill}>{skill}</b>):<small>暂未识别明确技能</small>}</div></div><div><span>待核实</span><div className="skill-tags missing">{item.missing_skills.length?item.missing_skills.map(skill=><b key={skill}>{skill}</b>):<small>没有硬技能缺口</small>}</div></div></div><ul className="reason-list">{item.reasons.slice(0,3).map(reason=><li key={reason}>{reason}</li>)}</ul>{item.job.verification_message&&<div className={`verification-note ${item.job.live_status}`}><strong>{liveStatusLabel(item.job.live_status)}</strong><span>{item.job.verification_message}</span>{item.job.verification_evidence.length>0&&<small>{item.job.verification_evidence.join(' · ')}</small>}</div>}{!item.formal_queue_eligible&&<div className="gate-note"><AlertTriangle size={14}/><span>进入正式队列前：{item.gate_reasons.join('；')}</span></div>}<footer><div><span className={`source-status ${item.job.live_status}`}>{liveStatusLabel(item.job.live_status)}{item.job.last_checked_at&&` · ${formatCheckedAt(item.job.last_checked_at)}`}</span><em title={item.gate_reasons.join('、')}>{item.formal_queue_eligible?'正式队列可用':item.queue_track==='stretch'?'挑战岗位':'稳妥岗位'}</em></div><div><a className="secondary" href={item.job.source_url} target="_blank" rel="noreferrer">来源<ExternalLink size={13}/></a><button className="secondary" disabled={!!busy} onClick={()=>verify(item)}>{busy===`verify:${item.job.id}`?<LoaderCircle className="spin" size={13}/>:<RefreshCw size={13}/>}官网核验</button><button className="secondary" disabled={queuedIds.has(item.job.id)||!!busy} onClick={()=>add([item.job.id])}>{queuedIds.has(item.job.id)?'已在清单':'加入清单'}</button><button className="primary" disabled={['closed','mismatch','unreachable'].includes(item.job.live_status)||!!busy} onClick={()=>begin(item)}>{busy===item.job.id?<LoaderCircle className="spin" size={15}/>:<Play size={15}/>} {['closed','mismatch','unreachable'].includes(item.job.live_status)?'暂不可投':item.job.live_status==='manual_gate'?'浏览器核验':item.job.apply_mode==='direct'?'开始投递':'打开选岗入口'}</button></div></footer></article>)}{!visible.length&&<div className="empty job-empty"><MapPin size={28}/><h2>当前筛选下没有岗位</h2><p>可以更换工作地点或公司后再试。</p></div>}</div>
    </section>
    <section className="card"><div className="library-head"><SectionTitle n={String(queue.length).padStart(2,'0')} title="我的候选投递清单" sub="可以先收藏；开始投递时会重新核验官网、届别和地点"/></div>{queue.length?<div className="queue-list">{queue.map(item=><article key={item.id}><div className="queue-company">{item.recommendation.job.company.slice(0,1)}</div><div><strong>{item.recommendation.job.title}</strong><span>{item.recommendation.job.company} · {item.recommendation.match_score}% 匹配 · {item.recommendation.formal_queue_eligible?'正式队列待开始':'待核实'}</span></div><button className="secondary" disabled={!!busy} onClick={()=>begin(item.recommendation,item.resume_id)}><Play size={14}/>开始投递</button><button className="queue-remove" title="从清单移除" disabled={!!busy} onClick={()=>remove(item.id)}><Trash2 size={14}/></button></article>)}</div>:<div className="empty queue-empty"><ListChecks size={28}/><h2>候选清单还是空的</h2><p>勾选上方推荐岗位，然后批量加入候选清单。</p></div>}</section>
  </div>
}

const liveStatusLabel=(status:LiveJobStatus)=>({not_checked:'等待实时核验',open:'官网实时可投',closed:'官网显示已关闭',manual_gate:'需浏览器核验',mismatch:'岗位信息不匹配',unreachable:'本次核验失败'}[status])
const formatCheckedAt=(value:string)=>{const date=new Date(value);return Number.isNaN(date.getTime())?value:date.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}

function ProfileEditor({profile,onSave}:{profile:CandidateProfile;onSave:(p:ResumeProfile)=>void}){
  const [draft,setDraft]=useState<ResumeProfile>(profile);useEffect(()=>setDraft(profile),[profile])
  const set=(key:keyof ResumeProfile,value:unknown)=>setDraft(d=>({...d,[key]:value}))
  return <div className="stack"><section className="card"><SectionTitle n="01" title="基本信息" sub="敏感信息只由你填写或确认"/><div className="form-grid three">
    <Input label="姓名" value={draft.name} set={v=>set('name',v)}/><Input label="英文姓名" value={draft.english_name} set={v=>set('english_name',v)}/><Select label="性别" value={draft.gender} values={['未识别','男','女','其他']} set={v=>set('gender',v)}/><Input label="出生日期" type="date" value={draft.birth_date} set={v=>set('birth_date',v)}/><Input label="年龄" type="number" value={draft.age} set={v=>set('age',v?Number(v):null)}/><Input label="手机号" value={draft.phone} set={v=>set('phone',v)}/><Input label="邮箱" type="email" value={draft.email} set={v=>set('email',v)}/><Input label="国家/地区" value={draft.country_region} set={v=>set('country_region',v)}/><Input label="QQ" value={draft.qq} set={v=>set('qq',v)}/><Input label="微信" value={draft.wechat} set={v=>set('wechat',v)}/><Input label="当前城市" value={draft.location} set={v=>set('location',v)}/><Input label="籍贯" value={draft.hometown} set={v=>set('hometown',v)}/><Input label="GitHub" value={draft.github} set={v=>set('github',v)}/><Input label="LinkedIn" value={draft.linkedin} set={v=>set('linkedin',v)}/><Input label="个人网站" value={draft.website} set={v=>set('website',v)}/></div><Text label="个人简介" value={draft.summary} set={v=>set('summary',v)}/></section>
    <section className="card"><SectionTitle n="02" title="求职偏好" sub="后续用于职位筛选和申请表单"/><div className="form-grid three"><Input label="目标岗位" value={draft.target_role} set={v=>set('target_role',v)}/><Input label="目标城市（逗号分隔）" value={draft.target_cities.join('，')} set={v=>set('target_cities',split(v))}/><Input label="目标行业（逗号分隔）" value={draft.target_industries.join('，')} set={v=>set('target_industries',split(v))}/><Input label="可入职时间" value={draft.available_date} set={v=>set('available_date',v)}/><Input label="实习时长" value={draft.internship_duration} set={v=>set('internship_duration',v)}/><Input label="每周可实习天数" value={draft.days_per_week} set={v=>set('days_per_week',v)}/><Input label="期望薪资" value={draft.expected_salary} set={v=>set('expected_salary',v)}/><Input label="远程偏好" value={draft.remote_preference} set={v=>set('remote_preference',v)}/></div></section>
    <EditableList title="教育经历" n="03" items={draft.education} empty={emptyEducation} set={v=>set('education',v)} render={(x,i,edit)=><div className="form-grid three"><Input label="学校" value={x.school} set={v=>edit(i,{school:v})}/><Input label="学院" value={x.college} set={v=>edit(i,{college:v})}/><Input label="专业" value={x.major} set={v=>edit(i,{major:v})}/><Input label="学历" value={x.degree} set={v=>edit(i,{degree:v})}/><Input label="就读地点" value={x.location} set={v=>edit(i,{location:v})}/><Input label="开始时间" value={x.start_date} set={v=>edit(i,{start_date:v})}/><Input label="毕业时间" value={x.end_date} set={v=>edit(i,{end_date:v})}/><Input label="GPA" value={x.gpa} set={v=>edit(i,{gpa:v})}/><Input label="排名" value={x.ranking} set={v=>edit(i,{ranking:v})}/></div>}/>
    <EditableList title="实习经历" n="04" items={draft.internships} empty={emptyExperience} set={v=>set('internships',v)} render={(x,i,edit)=><><div className="form-grid three"><Input label="公司/组织" value={x.organization} set={v=>edit(i,{organization:v})}/><Input label="部门" value={x.department} set={v=>edit(i,{department:v})}/><Input label="职位" value={x.role} set={v=>edit(i,{role:v})}/><Input label="地点" value={x.location} set={v=>edit(i,{location:v})}/><Input label="开始时间" value={x.start_date} set={v=>edit(i,{start_date:v})}/><Input label="结束时间" value={x.end_date} set={v=>edit(i,{end_date:v})}/></div><Text label="工作内容" value={x.description} set={v=>edit(i,{description:v})}/></>}/>
    <EditableList title="项目经历" n="05" items={draft.projects} empty={emptyProject} set={v=>set('projects',v)} render={(x,i,edit)=><><div className="form-grid three"><Input label="项目名称" value={x.name} set={v=>edit(i,{name:v})}/><Input label="角色" value={x.role} set={v=>edit(i,{role:v})}/><Input label="开始时间" value={x.start_date} set={v=>edit(i,{start_date:v})}/><Input label="结束时间" value={x.end_date} set={v=>edit(i,{end_date:v})}/><Input label="技术栈（逗号分隔）" value={x.technologies.join('，')} set={v=>edit(i,{technologies:split(v)})}/><Input label="GitHub" value={x.github_url} set={v=>edit(i,{github_url:v})}/></div><Text label="项目描述" value={x.description} set={v=>edit(i,{description:v})}/></>}/>
    <section className="card"><SectionTitle n="06" title="技能与补充资料" sub="使用逗号分隔多个项目"/><div className="form-grid two"><Text label="技能" value={draft.skills.join('，')} set={v=>set('skills',split(v))}/><Text label="语言能力" value={draft.languages.join('，')} set={v=>set('languages',split(v))}/><Text label="证书" value={draft.certificates.join('，')} set={v=>set('certificates',split(v))}/><Text label="奖项" value={draft.awards.join('，')} set={v=>set('awards',split(v))}/></div></section>
    <SavedAnswersEditor answers={draft.application_answers} set={value=>set('application_answers',value)}/>
    <div className="sticky-save"><span>主档案是 Agent 后续工作的事实基础</span><button className="primary" onClick={()=>onSave(draft)}><Save size={17}/>保存主档案</button></div></div>}

function SavedAnswersEditor({answers,set}:{answers:Record<string,string>;set:(answers:Record<string,string>)=>void}){const entries=Object.entries(answers);const change=(oldQuestion:string,question:string,value:string)=>{const next={...answers};delete next[oldQuestion];if(question.trim())next[question.trim()]=value;set(next)};return <section className="card"><SectionTitle n="07" title="常用申请答案" sub="从填表页主动同步的非敏感答案，之后可复用"/>{entries.length?<div className="saved-answer-list">{entries.map(([question,value])=><div key={question}><input aria-label="问题" value={question} onChange={e=>change(question,e.target.value,value)}/><input aria-label="答案" value={value} onChange={e=>change(question,question,e.target.value)}/><button className="danger" onClick={()=>{const next={...answers};delete next[question];set(next)}}>删除</button></div>)}</div>:<p className="saved-answer-empty">还没有常用答案。在网站 Demo 的表单分析结果中点击“同步主档案”后会出现在这里。</p>}</section>}

function ResumeLibrary({resumes,busy,upload,onReview,onRefresh,onDefault,onDelete}:{resumes:ResumeRecord[];busy:boolean;upload:()=>void;onReview:(id:string)=>void;onRefresh:(r:ResumeRecord)=>void;onDefault:(r:ResumeRecord)=>void;onDelete:(r:ResumeRecord)=>void}){return <section className="card"><div className="library-head"><SectionTitle n={String(resumes.length).padStart(2,'0')} title="简历版本" sub="支持 PDF、DOCX、TXT，单份最大 10MB"/><button className="primary" onClick={upload}><UploadCloud size={17}/>上传简历</button></div>{!resumes.length?<div className="empty"><UploadCloud size={30}/><h2>还没有简历</h2><p>上传后，Agent 会自动拆分并合并到主档案。</p></div>:<div className="resume-grid">{resumes.map(r=><article className="resume-card" key={r.id}><div className="file-icon"><Files size={22}/></div><div className="resume-main"><div><h3>{r.label}{r.is_default&&<em>默认</em>}</h3><p>{r.filename}</p></div><div className="tag-row"><span>{r.language}</span><span>{formatBytes(r.file_size)}</span><span>{r.status==='failed'?'解析失败':r.status==='parsing'?'解析中':r.parser==='local-rules'?'本地解析':'AI 解析'}</span></div><small>{r.status==='failed'?(r.error_message||'模型服务暂时不可用，请重新解析'):`${r.evidence.filter(e=>e.status==='pending_review').length} 个字段待确认 · ${new Date(r.updated_at).toLocaleDateString('zh-CN')}`}</small></div><div className="actions"><button disabled={r.status==='failed'||r.status==='parsing'} onClick={()=>onReview(r.id)}>检查</button><a href={`${API}/resumes/${r.id}/download`}><Download size={15}/></a><button title="重新解析" disabled={busy||r.status==='parsing'} onClick={()=>onRefresh(r)}><RefreshCw size={15}/></button>{!r.is_default&&<button title="设为默认" disabled={r.status==='failed'||r.status==='parsing'} onClick={()=>onDefault(r)}><Check size={15}/></button>}<button className="danger" title="删除" onClick={()=>onDelete(r)}><Trash2 size={15}/></button></div></article>)}</div>}</section>}

function ReviewWorkspace({resumes,active,conflicts,rawText,select,notify,onReviewed,onResolved}:{resumes:ResumeRecord[];active:ResumeRecord|null;conflicts:Conflict[];rawText:string;select:(id:string)=>void;notify:(v:string)=>void;onReviewed:(r:ResumeRecord)=>Promise<void>;onResolved:(id:string,c:'current'|'incoming'|'custom',v?:unknown)=>void}){
  const [tab,setTab]=useState<'fields'|'conflicts'>('fields')
  const [sourceView,setSourceView]=useState<'file'|'text'>('file')
  useEffect(()=>setSourceView('file'),[active?.id])
  const pendingEvidence=active?.evidence.filter(e=>e.status==='pending_review')??[]
  return <div className="stack"><div className="review-toolbar"><select value={active?.id||''} onChange={e=>select(e.target.value)}><option value="">选择简历</option>{resumes.map(r=><option value={r.id} key={r.id}>{r.label}</option>)}</select><div><button className={tab==='fields'?'active':''} onClick={()=>setTab('fields')}>识别字段</button><button className={tab==='conflicts'?'active':''} onClick={()=>setTab('conflicts')}>资料冲突 <b>{conflicts.length}</b></button></div></div>
    {tab==='conflicts'?<ConflictList conflicts={conflicts} resolve={onResolved}/>:!active?<div className="card empty"><Files size={28}/><h2>选择一份简历开始检查</h2></div>:<div className="review-grid"><section className="card source"><div className="source-head"><div><h2>{sourceView==='file'?'原始文件预览':'提取文本'}</h2><p>{active.filename}</p></div><div className="source-head-tools"><div className="source-switch"><button className={sourceView==='file'?'active':''} onClick={()=>setSourceView('file')}><Files size={13}/>原始文件</button><button className={sourceView==='text'?'active':''} onClick={()=>setSourceView('text')}><FileText size={13}/>提取文本</button></div><a href={`${API}/resumes/${active.id}/download`} title="下载原始文件"><Download size={15}/></a></div></div>{sourceView==='file'?<iframe className="source-frame" title={`${active.filename} 原始文件预览`} src={`${API}/resumes/${active.id}/preview`}/>:<pre>{rawText||'正在读取提取文本…'}</pre>}</section><section className="card evidence"><div className="source-head"><div><h2>Agent 识别结果</h2><p>处理后会自动从待确认列表收起</p></div><span>{pendingEvidence.length} 待处理</span></div>{pendingEvidence.length?pendingEvidence.map(e=><EvidenceItem key={e.id} item={e} notify={notify} act={async(status,value)=>onReviewed(await api.review(active.id,e.id,status,value))}/>):<div className="success-empty"><ShieldCheck size={30}/><h3>这份简历已检查完成</h3><p>所有字段均已确认、修改或拒绝。</p></div>}</section></div>}</div>}
function EvidenceItem({item,act,notify}:{item:Evidence;act:(s:string,v?:unknown)=>Promise<void>;notify:(v:string)=>void}){const [editing,setEditing]=useState(false);const [value,setValue]=useState(typeof item.value==='string'?item.value:JSON.stringify(item.value,undefined,2));const tone=item.confidence>=.9?'high':item.confidence>=.75?'medium':'low';const submit=async(status:string,next?:unknown)=>{try{await act(status,next);if(status==='edited')notify(`${labels[item.field_path]??item.field_path}已同步到简历版本和主档案。`);return true}catch(e){notify(message(e));return false}};const save=async()=>{let parsed:unknown=value;if(typeof item.value!=='string'){try{parsed=JSON.parse(value)}catch{notify('列表或经历字段必须是有效的 JSON，请检查括号和引号。');return}}if(await submit('edited',parsed))setEditing(false)};return <article className={`evidence-item ${item.status}`}><div className="evidence-top"><strong>{labels[item.field_path]??item.field_path}</strong><span className={tone}>{Math.round(item.confidence*100)}% 置信度</span></div>{editing?<textarea value={value} onChange={e=>setValue(e.target.value)}/>:<div className="evidence-value">{value}</div>}<blockquote>{item.source_text||'未找到直接原文'}</blockquote><div className="evidence-actions"><span>等待确认</span>{editing?<><button onClick={save}>保存修改</button><button onClick={()=>setEditing(false)}>取消</button></>:<><button onClick={()=>submit('confirmed')}><Check size={14}/>确认</button><button onClick={()=>setEditing(true)}>修改</button><button className="reject" onClick={()=>submit('rejected')}>拒绝</button></>}</div></article>}
function ConflictList({conflicts,resolve}:{conflicts:Conflict[];resolve:(id:string,c:'current'|'incoming'|'custom',v?:unknown)=>void}){return <section className="card"><SectionTitle n={String(conflicts.length).padStart(2,'0')} title="资料冲突" sub="新简历不会静默覆盖主档案，请选择真实信息"/>{!conflicts.length?<div className="success-empty"><ShieldCheck size={30}/><h3>没有待处理冲突</h3><p>主档案中的信息目前一致。</p></div>:<div className="conflict-list">{conflicts.map(c=><article key={c.id}><div><span>{labels[c.field_path]??c.field_path}</span><small>来自：{c.resume_label}</small></div><button onClick={()=>resolve(c.id,'current')}><small>保留主档案</small><strong>{display(c.current_value)}</strong></button><button onClick={()=>resolve(c.id,'incoming')}><small>采用新简历</small><strong>{display(c.incoming_value)}</strong></button></article>)}</div>}</section>}

function BrowserDemo({profile,resumes,notify,onProfileUpdate,initialJob,initialResumeId}:{profile:CandidateProfile|null;resumes:ResumeRecord[];notify:(v:string)=>void;onProfileUpdate:(profile:CandidateProfile)=>void;initialJob:JobRecommendation|null;initialResumeId:string}){
  const defaultResumeId=initialResumeId||(resumes.find(item=>item.is_default)??resumes[0])?.id||''
  const initialResume=resumes.find(item=>item.id===defaultResumeId)
  const [url,setUrl]=useState(initialJob?.job.url||'https://join.qq.com/post_detail.html?postid=1282707395466077184');const [snapshot,setSnapshot]=useState<BrowserSnapshot|null>(null);const [workflow,setWorkflow]=useState<ApplicationWorkflowState|null>(null);const [verificationCode,setVerificationCode]=useState('');const [registrationEmail,setRegistrationEmail]=useState(profile?.email||'');const [registrationPhone,setRegistrationPhone]=useState(profile?.phone||'');const [registrationPassword,setRegistrationPassword]=useState('');const [plan,setPlan]=useState<FormPlan|null>(null);const [comparisons,setComparisons]=useState<FieldComparison[]>([]);const [nativeImport,setNativeImport]=useState<NativeResumeImportResult|null>(null);const [showMatched,setShowMatched]=useState(false);const [execution,setExecution]=useState<ExecutionResult|null>(null);const [check,setCheck]=useState<PreSubmitCheck|null>(null);const [answers,setAnswers]=useState<Record<string,string>>({});const [skippedSelectors,setSkippedSelectors]=useState<Set<string>>(new Set());const [editingSelectors,setEditingSelectors]=useState<Set<string>>(new Set());const [selectedResume,setSelectedResume]=useState(defaultResumeId);const [busy,setBusy]=useState('')
  useEffect(()=>{if(initialJob?.job.url)setUrl(initialJob.job.url)},[initialJob?.job.id,initialJob?.job.url])
  useEffect(()=>{if(initialResumeId)setSelectedResume(initialResumeId)},[initialResumeId])
  useEffect(()=>{setRegistrationEmail(profile?.email||'');setRegistrationPhone(profile?.phone||'')},[profile?.email,profile?.phone])
  const resetReview=()=>{setPlan(null);setComparisons([]);setExecution(null);setCheck(null);setAnswers({});setSkippedSelectors(new Set());setEditingSelectors(new Set())}
  const start=async()=>{setBusy('opening');resetReview();setNativeImport(null);setWorkflow(null);setVerificationCode('');try{const data=await api.startBrowser(url);setSnapshot(data);const state=await api.workflowState(data.session_id);setWorkflow(state);notify(`已打开 ${data.title||data.url}，当前阶段：${workflowStageLabel(state.stage)}。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const refreshWorkflow=async()=>{if(!snapshot)return;setBusy('refreshing');try{const [state,fresh]=await Promise.all([api.advanceWorkflow(snapshot.session_id,'refresh'),api.browserSnapshot(snapshot.session_id)]);setWorkflow(state);setSnapshot(fresh);setNativeImport(null);resetReview();notify(`已重新识别，当前阶段：${workflowStageLabel(state.stage)}。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const enterApplication=async()=>{if(!snapshot)return;setBusy('advancing');try{const state=await api.advanceWorkflow(snapshot.session_id,'start_application');setWorkflow(state);setSnapshot(await api.browserSnapshot(snapshot.session_id));notify(state.message)}catch(e){notify(message(e))}finally{setBusy('')}}
  const requestCode=async()=>{if(!snapshot||!workflow)return;setBusy('requesting-code');try{const channel=workflow.verification_channel==='email'?'email':'phone';const value=workflow.stage==='registration_required'?(channel==='email'?registrationEmail:registrationPhone):'';setWorkflow(await api.requestVerificationCode(snapshot.session_id,channel,value));notify(`已使用当前${channel==='email'?'邮箱':'手机号'}请求验证码。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const enterCode=async(submit:boolean)=>{if(!snapshot||!verificationCode)return;setBusy('verifying');try{const state=await api.enterVerificationCode(snapshot.session_id,verificationCode,submit);setVerificationCode('');setWorkflow(state);setSnapshot(await api.browserSnapshot(snapshot.session_id));notify(submit?'验证码已填入并尝试继续。':'验证码已填入，等待你在浏览器中确认。')}catch(e){notify(message(e))}finally{setVerificationCode('');setBusy('')}}
  const fillRegistration=async()=>{if(!snapshot||!registrationPassword)return;setBusy('registering');try{setWorkflow(await api.fillRegistration(snapshot.session_id,registrationEmail,registrationPhone,registrationPassword));setSnapshot(await api.browserSnapshot(snapshot.session_id));notify('注册信息已填入 Chrome；密码已从智达页面内存清除，请去 Chrome 核对并亲自勾选协议。')}catch(e){notify(message(e))}finally{setRegistrationPassword('');setBusy('')}}
  const createAccount=async()=>{if(!snapshot)return;setBusy('creating-account');try{const state=await api.advanceWorkflow(snapshot.session_id,'create_account');setWorkflow(state);setSnapshot(await api.browserSnapshot(snapshot.session_id));notify(`已执行创建账号，当前阶段：${workflowStageLabel(state.stage)}。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const analyze=async()=>{if(!snapshot)return;setBusy('planning');resetReview();try{const result=await api.reviewForm(snapshot.session_id);setSnapshot(result.snapshot);setPlan(result.plan);setComparisons(result.comparisons);notify(`核对完成：${result.summary.matched} 项一致，${result.summary.missing} 项漏填，${result.summary.conflict} 项冲突。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const analyzeWithAI=async()=>{if(!snapshot)return;setBusy('ai-planning');resetReview();try{const result=await api.reviewForm(snapshot.session_id,true);setSnapshot(result.snapshot);setPlan(result.plan);setComparisons(result.comparisons);notify(`AI 深度分析完成：仍有 ${result.summary.manual_review+result.summary.unmapped+result.summary.option_unavailable} 项需要人工处理。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const importWithSite=async()=>{if(!snapshot||!selectedResume)return;setBusy('site-parsing');resetReview();try{const imported=await api.importResumeWithSite(snapshot.session_id,selectedResume);setNativeImport(imported);setSnapshot(imported.snapshot);notify(imported.message);const result=await api.reviewForm(snapshot.session_id);setSnapshot(result.snapshot);setPlan(result.plan);setComparisons(result.comparisons)}catch(e){notify(message(e))}finally{setBusy('')}}
  const expandSection=async(field:PageField)=>{if(!snapshot)return;setBusy('expanding');try{await api.expandBrowserSection(snapshot.session_id,field.selector);setAnswers({});setSkippedSelectors(new Set());setEditingSelectors(new Set());setExecution(null);setCheck(null);const result=await api.reviewForm(snapshot.session_id);setSnapshot(result.snapshot);setPlan(result.plan);setComparisons(result.comparisons);notify(`已在招聘网页展开“${field.group_label||field.label}”，并重新核对 ${result.snapshot.fields.length} 个字段。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const answer=(action:FillAction,value:string)=>setAnswers(current=>{const next={...current};if(value)next[action.selector]=value;else delete next[action.selector];return next})
  const radioKey=(field:PageField)=>field.group_label||field.name||field.label
  const answerRadio=(field:PageField,selector:string)=>setAnswers(current=>{const next={...current};snapshot?.fields.filter(item=>item.field_type==='radio'&&radioKey(item)===radioKey(field)).forEach(item=>delete next[item.selector]);if(selector)next[selector]='true';return next})
  const answerMulti=(action:FillAction,option:string,checked:boolean)=>setAnswers(current=>{const values=new Set(split(current[action.selector]||''));checked?values.add(option):values.delete(option);const next={...current};const value=[...values].join('，');if(value)next[action.selector]=value;else delete next[action.selector];return next})
  const toggleSkip=(selector:string)=>setSkippedSelectors(current=>{const next=new Set(current);next.has(selector)?next.delete(selector):next.add(selector);return next})
  const toggleEdit=(selector:string)=>setEditingSelectors(current=>{const next=new Set(current);next.has(selector)?next.delete(selector):next.add(selector);return next})
  const remember=async(action:FillAction)=>{const value=answers[action.selector]?.trim();const field=snapshot?.fields.find(f=>f.selector===action.selector);if(!value||!field)return;setBusy('remembering');try{const updated=await api.saveApplicationAnswer(field.label||action.label,field.name,value);onProfileUpdate(updated);notify(`“${field.label||action.label}”已同步到主档案，之后遇到同样问题会自动建议。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const preparedActions=useMemo(()=>plan?.actions.map(action=>{if(skippedSelectors.has(action.selector))return {...action,action:'skip' as const,value:'',reason:'用户选择本次不填写'};const manual=answers[action.selector];if(!manual)return action;const field=snapshot?.fields.find(f=>f.selector===action.selector);const kind=field?.field_type;return {...action,action:(kind==='select-one'||kind==='select-multiple'||kind==='combobox'?'select':kind==='checkbox'||kind==='radio'?'check':'fill') as FillAction['action'],value:kind==='checkbox'||kind==='radio'?manual==='true':manual,confidence:1,sensitive:false,user_confirmed:true,value_source:'用户在提交前补充'}})??[],[plan,answers,snapshot,skippedSelectors])
  const readyCount=preparedActions.filter(a=>['fill','select','check'].includes(a.action)&&(a.action==='check'||String(a.value).trim())&&(!a.sensitive||a.user_confirmed)&&a.confidence>=.85).length
  const needsInput=plan?.actions.filter(action=>{const field=snapshot?.fields.find(f=>f.selector===action.selector);if(!field||field.field_type==='file')return false;const emptyAction=!['fill','select','check'].includes(action.action)||(action.action!=='check'&&!String(action.value).trim());const websiteFilled=field.field_type==='radio'?Boolean(snapshot?.fields.some(item=>item.field_type==='radio'&&radioKey(item)===radioKey(field)&&item.current_value==='true')):field.field_type==='checkbox'?field.current_value==='true':Boolean(field.current_value&&!/^(select|choose|请选择|未选择|暂未选择)/i.test(field.current_value));return action.action==='ask_user'||action.sensitive||Boolean(field.required&&emptyAction&&!websiteFilled)})??[]
  const manualGroups=useMemo(()=>{const groups:{key:string;label:string;kind:'radio'|'field';actions:FillAction[];fields:PageField[]}[]=[];const seen=new Set<string>();for(const action of needsInput){const field=snapshot?.fields.find(item=>item.selector===action.selector);if(!field)continue;if(field.field_type==='radio'){const key=`radio:${radioKey(field)}`;if(seen.has(key))continue;seen.add(key);const fields=snapshot?.fields.filter(item=>item.field_type==='radio'&&radioKey(item)===radioKey(field))??[];const selectors=new Set(fields.map(item=>item.selector));groups.push({key,label:field.group_label||action.label,kind:'radio',fields,actions:needsInput.filter(item=>selectors.has(item.selector))})}else{groups.push({key:action.selector,label:field.group_label||action.label,kind:'field',fields:[field],actions:[action]})}}return groups},[needsInput,snapshot])
  const visibleActions=useMemo(()=>{const seen=new Set<string>();return plan?.actions.filter(action=>{const field=snapshot?.fields.find(item=>item.selector===action.selector);if(field?.field_type!=='radio')return true;const key=radioKey(field);if(seen.has(key))return false;seen.add(key);return true})??[]},[plan,snapshot])
  const visibleComparisons=showMatched?comparisons:comparisons.filter(item=>item.status!=='matched')
  const unresolvedGroups=manualGroups.filter(group=>group.kind==='radio'?!group.fields.some(field=>answers[field.selector]==='true'):!answers[group.actions[0]?.selector]&&!skippedSelectors.has(group.actions[0]?.selector))
  const overallReady=Boolean(check?.ready)&&unresolvedGroups.length===0&&!execution?.failed
  const continueStep=async()=>{if(!snapshot||!overallReady)return;setBusy('continuing');try{const state=await api.advanceWorkflow(snapshot.session_id,'continue_application');const fresh=await api.browserSnapshot(snapshot.session_id);setWorkflow(state);setSnapshot(fresh);setNativeImport(null);resetReview();notify(`已安全进入下一页，当前阶段：${workflowStageLabel(state.stage)}。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const execute=async()=>{if(!snapshot||!plan)return;setBusy('filling');try{const result=await api.executeForm(snapshot.session_id,preparedActions,selectedResume);setExecution(result);setCheck(result.pre_submit);setSnapshot(await api.browserSnapshot(snapshot.session_id));notify(`填写完成：${result.verified} 项已回读验证，${result.failed} 项失败，仍有 ${result.pre_submit.required_missing.length} 个必填项缺失。`)}catch(e){notify(message(e))}finally{setBusy('')}}
  const recheck=async()=>{if(!snapshot)return;setBusy('checking');try{setCheck(await api.checkForm(snapshot.session_id));notify('已重新检查当前网页。')}catch(e){notify(message(e))}finally{setBusy('')}}
  const close=async()=>{if(snapshot)await api.closeBrowser(snapshot.session_id).catch(()=>{});setSnapshot(null);setWorkflow(null);setVerificationCode('');setRegistrationPassword('');setNativeImport(null);resetReview();notify('浏览器 Demo 会话已结束。')}
  const canAnalyze=workflow?.stage==='application_form'||workflow?.stage==='profile_form'||workflow?.stage==='review'
  return <div className="stack demo-workspace"><section className="card demo-intro"><div><span className="demo-icon"><WandSparkles size={22}/></span><div><h2>多公司投递工作台</h2><p>通用状态机管理登录、验证、表单填写与回读；腾讯是第一个真实适配站点。</p></div></div><div className="safety-note"><ShieldCheck size={16}/><span>不会点击最终提交<br/><small>隐私同意、登录授权和人机验证由你完成</small></span></div></section>
    {initialJob&&<div className="selected-job-banner"><Target size={18}/><div><span>从推荐清单进入</span><strong>{initialJob.job.company} · {initialJob.job.title}</strong><small>{initialJob.match_score}% 匹配 · URL 已自动带入{initialResume?` · 简历：${initialResume.label}`:''}，下方点击“打开浏览器”即可开始</small></div></div>}
    <section className="card"><SectionTitle n="01" title="打开招聘页面" sub="支持企业自建站与常见 ATS；未适配站点会退回通用表单识别"/><div className="url-row"><label className="field"><span>职位详情或申请页 URL</span><input value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://company.example/jobs/..." onKeyDown={e=>e.key==='Enter'&&start()}/></label>{snapshot?<button className="secondary" onClick={close}><X size={16}/>结束会话</button>:<button className="primary" disabled={!url||!!busy} onClick={start}>{busy==='opening'?<LoaderCircle className="spin" size={17}/>:<ExternalLink size={17}/>}打开浏览器</button>}</div>{snapshot&&<div className="browser-status"><span className="live-dot"/><div><strong>{snapshot.title||'招聘页面'}</strong><small>{snapshot.url}</small></div><em>{snapshot.fields.length} 个字段</em></div>}</section>
    {workflow&&<section className="card workflow-card"><div className="library-head"><SectionTitle n="02" title="投递流程导航" sub="Agent 先判断页面阶段，再只执行当前阶段的安全动作"/><button className="secondary" disabled={!!busy} onClick={refreshWorkflow}>{busy==='refreshing'?<LoaderCircle className="spin" size={16}/>:<RefreshCw size={16}/>}重新识别</button></div><WorkflowJourney stage={workflow.stage}/><div className="workflow-state"><div><span className={`stage-dot ${workflow.stage}`}/><div><strong>{workflowStageLabel(workflow.stage)}</strong><small>{workflow.adapter} {workflow.job_id&&`· 职位 ${workflow.job_id}`}</small></div></div><em>{workflow.page_step_current&&workflow.page_step_total?`网页第 ${workflow.page_step_current}/${workflow.page_step_total} 步`:`${workflow.form_fields} 个表单字段`}</em></div><p className="workflow-message">{workflow.message}</p>
      {workflow.authentication_methods.length>0&&<div className="method-row"><span>可用方式</span>{workflow.authentication_methods.map(method=><b key={method}>{method}</b>)}</div>}
      {workflow.requires_consent&&<div className="human-gate"><AlertTriangle size={17}/><span><strong>需要你亲自确认</strong><small>请在打开的 Chrome 中阅读并决定是否同意隐私政策，Agent 不会代你勾选。</small></span></div>}
      {workflow.stage==='registration_required'&&<div className="registration-panel"><div><strong>一次性注册信息</strong><small>仅填入当前 Chrome，不存入账号库、主档案或日志</small></div><div className="registration-grid">{(!workflow.registration_identifiers.length||workflow.registration_identifiers.includes('email'))&&<label className="verification-input"><span>邮箱</span><input type="email" autoComplete="email" value={registrationEmail} onChange={e=>setRegistrationEmail(e.target.value)}/></label>}{workflow.registration_identifiers.includes('phone')&&<label className="verification-input"><span>手机号</span><input type="tel" autoComplete="tel" value={registrationPhone} onChange={e=>setRegistrationPhone(e.target.value)}/></label>}{workflow.registration_requires_password&&<label className="verification-input"><span>本次注册密码</span><input type="password" autoComplete="new-password" value={registrationPassword} onChange={e=>setRegistrationPassword(e.target.value)} placeholder="至少 8 位，填入后立即清除"/></label>}</div></div>}
      <div className="workflow-actions">{workflow.stage==='job_detail'&&<button className="primary" disabled={!!busy} onClick={enterApplication}>{busy==='advancing'?<LoaderCircle className="spin" size={17}/>:<ExternalLink size={17}/>}进入登录/申请流程</button>}{workflow.stage==='registration_required'&&<><button className="secondary" disabled={(workflow.registration_requires_password&&!registrationPassword)||!!busy} onClick={fillRegistration}>{busy==='registering'?<LoaderCircle className="spin" size={16}/>:<Save size={16}/>}填入注册信息</button><button className="primary" disabled={!!busy} onClick={createAccount}>{busy==='creating-account'?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>}我已核对并同意，创建账号</button></>}{workflow.stage==='auth_required'&&<button className="primary" disabled={!!busy} onClick={refreshWorkflow}><RefreshCw size={16}/>我已完成登录，重新识别</button>}{(workflow.stage==='verification_required'||workflow.stage==='registration_required'&&Boolean(workflow.verification_channel))&&<><button className="secondary" disabled={!!busy} onClick={requestCode}>获取验证码</button><label className="verification-input"><span>本次验证码</span><input type="password" inputMode="numeric" autoComplete="one-time-code" value={verificationCode} onChange={e=>setVerificationCode(e.target.value)} placeholder="仅保留在当前页面内存"/></label><button className="secondary" disabled={!verificationCode||!!busy} onClick={()=>enterCode(false)}>只填入</button><button className="primary" disabled={!verificationCode||!!busy} onClick={()=>enterCode(true)}>填入并继续</button></>}{canAnalyze&&<button className="primary" disabled={!!busy} onClick={analyze}><Sparkles size={17}/>分析当前表单</button>}</div>
      {workflow.final_submit_present&&<div className="submit-boundary"><ShieldCheck size={15}/>已识别最终提交按钮，系统不会点击。</div>}
    </section>}
    <section className={`card ${!canAnalyze?'disabled-card':''}`}>
      <div className="library-head"><SectionTitle n="03" title="网站解析 + 智达核对" sub={`先利用招聘网站解析简历，再与 ${profile?.name||'当前候选人'} 的已确认主档案逐项比对`}/><div className="review-buttons"><button className="secondary" disabled={!snapshot||!canAnalyze||!!busy} onClick={analyzeWithAI}>{busy==='ai-planning'?<LoaderCircle className="spin" size={16}/>:<Sparkles size={16}/>}AI 分析剩余项</button><button className="primary" disabled={!snapshot||!canAnalyze||!!busy} onClick={analyze}>{busy==='planning'?<LoaderCircle className="spin" size={17}/>:<ListChecks size={17}/>}立即核对</button></div></div>
      <div className="native-parser-toolbar"><label className="field"><span>用于网站解析的简历</span><select value={selectedResume} onChange={e=>setSelectedResume(e.target.value)}><option value="">请选择一份简历</option>{resumes.map(r=><option value={r.id} key={r.id}>{r.label}{r.is_default?' · 默认':''}</option>)}</select></label><button className="secondary" disabled={!snapshot||!canAnalyze||!selectedResume||!!busy} onClick={importWithSite}>{busy==='site-parsing'?<LoaderCircle className="spin" size={16}/>:<UploadCloud size={16}/>}让招聘网站先解析</button></div>
      {nativeImport&&<div className={`native-import-result ${nativeImport.status}`}><Files size={18}/><span><strong>{nativeImport.uploaded_file}</strong><small>{nativeImport.message}{nativeImport.trigger_clicked&&` · 已点击“${nativeImport.trigger_label}”`}</small></span><em>{nativeImport.changed_fields} 个字段变化</em></div>}
      {snapshot&&!plan&&<div className="field-preview">{snapshot.fields.slice(0,8).map(field=><span key={field.selector}>{field.group_label||field.label||field.name||field.field_type}{field.required&&<b>*</b>}</span>)}{snapshot.fields.length>8&&<span>+{snapshot.fields.length-8}</span>}</div>}
      {plan&&<>
        <div className="plan-summary"><div><strong>{plan.site_type}</strong><span>{plan.page_summary}</span></div><div><b>{readyCount}</b><small>需要补填/纠正</small></div><div><b>{unresolvedGroups.length}</b><small>等待用户回答</small></div></div>
        {comparisons.length>0&&<div className="comparison-panel"><div className="comparison-head"><div><strong>网站解析核对</strong><small>网站现值与已确认主档案的差异</small></div><div className="comparison-counts"><span className="matched">一致 {comparisons.filter(x=>x.status==='matched').length}</span><span className="missing">漏填 {comparisons.filter(x=>x.status==='missing').length}</span><span className="conflict">冲突 {comparisons.filter(x=>x.status==='conflict').length}</span><span className="manual_review">人工核对 {comparisons.filter(x=>x.status==='manual_review'||x.status==='unmapped'||x.status==='option_unavailable').length}</span><button onClick={()=>setShowMatched(value=>!value)}>{showMatched?'隐藏一致项':'查看一致项'}</button></div></div><div className="comparison-list">{visibleComparisons.length?visibleComparisons.map(item=><article className={`comparison-item ${item.status}`} key={item.key}><div className="comparison-title"><strong>{item.label}{item.required&&<b>*</b>}</strong><span>{comparisonStatusLabel(item.status)}</span></div><div className="comparison-values"><p><small>招聘网站</small><b>{item.site_value||'未填写'}</b></p><p><small>智达主档案</small><b>{item.expected_value||'没有可靠值'}</b></p></div>{item.options.length>0&&item.status!=='matched'&&<div className="comparison-options"><small>网页真实选项</small><span>{item.options.slice(0,12).join(' · ')}{item.options.length>12?' …':''}</span></div>}<footer>{item.recommendation}{item.value_source&&` · ${item.value_source}`}</footer></article>):<div className="success-empty compact"><ShieldCheck size={24}/><h3>所有可核对字段均一致</h3></div>}</div></div>}
        <div className="action-list">{visibleActions.map((action,i)=>{const field=snapshot?.fields.find(f=>f.selector===action.selector);const skipped=skippedSelectors.has(action.selector);const editing=editingSelectors.has(action.selector);const isToggle=field?.field_type==='radio'||field?.field_type==='checkbox';const manual=answers[action.selector];const canEdit=Boolean(field&&field.field_type!=='file'&&!isToggle);const shown=manual||display(action.value)||action.reason;return <article key={`${action.selector}-${i}`} className={skipped?'will-skip':manual?'ready':action.action==='ask_user'||action.sensitive?'needs-user':action.action==='skip'?'will-skip':'ready'}><span>{skipped?'本次跳过':manual?'已修改':action.action==='fill'?'填写':action.action==='select'?'选择':action.action==='check'?'勾选':action.action==='ask_user'?'询问':'无需填写'}</span><div><div className="action-heading"><strong>{field?.group_label||action.label}</strong><div>{canEdit&&<button onClick={()=>toggleEdit(action.selector)}>{editing?'收起':'修改'}</button>}{field?.field_type!=='file'&&field?.field_type!=='radio'&&<button onClick={()=>toggleSkip(action.selector)}>{skipped?'恢复':'不填写'}</button>}</div></div>{editing&&canEdit?<div className="inline-answer">{field?.options.length?<select value={manual||String(action.value||'')} onChange={e=>answer(action,e.target.value)}><option value="">请选择</option>{field.options.map(option=><option value={option} key={option}>{option}</option>)}</select>:<input value={manual??String(action.value||'')} onChange={e=>answer(action,e.target.value)} placeholder="在这里补充或修改"/>}{!action.sensitive&&<button disabled={!answers[action.selector]||!!busy} onClick={()=>remember(action)}><Save size={13}/>同步主档案</button>}</div>:<p>{shown}</p>}<small>{manual?'由用户明确确认':action.value_source||action.reason}{action.sensitive&&' · 仅当前投递使用，不自动记忆'}</small></div><em>{manual?'100':Math.round(action.confidence*100)}%</em></article>})}</div>
      </>}
    </section>
    {plan&&<section className="card"><SectionTitle n="04" title="人工确认与简历" sub="第三方信息、是/否和主观偏好必须由你明确选择"/><div className="form-grid two"><label className="field"><span>本次上传的简历</span><select value={selectedResume} onChange={e=>setSelectedResume(e.target.value)}><option value="">不自动上传</option>{resumes.map(r=><option value={r.id} key={r.id}>{r.label}{r.is_default?' · 默认':''}</option>)}</select></label></div>{manualGroups.length?<div className="answer-list">{manualGroups.map(group=>{const action=group.actions[0];const field=group.fields[0];if(group.kind==='radio'){const selected=group.fields.find(item=>answers[item.selector]==='true')?.selector||'';return <label className="answer-row" key={group.key}><span><strong>{group.label}</strong><small>{action?.reason||'请选择网页提供的真实选项'}</small></span><select value={selected} onChange={e=>answerRadio(field,e.target.value)}><option value="">暂不填写</option>{group.fields.map(option=><option value={option.selector} key={option.selector}>{option.option_label||option.option_value||option.label}</option>)}</select></label>}return <div className="answer-row" key={group.key}><span><strong>{group.label}</strong><small>{action?.reason||'主档案中没有可靠答案'} · 网页控件：{controlKind(field)}{field.field_type==='combobox'&&!field.options.length&&'；暂未读取到选项，执行时还会再次匹配'}</small></span><div className="manual-control">{field.field_type==='section-button'?<button type="button" className="secondary expand-section" disabled={!!busy} onClick={()=>expandSection(field)}>{busy==='expanding'?<LoaderCircle className="spin" size={15}/>:<Plus size={15}/>}在招聘网页展开并重新分析</button>:field.field_type==='checkbox'?<select value={answers[action.selector]||''} onChange={e=>answer(action,e.target.value)}><option value="">暂不填写</option><option value="true">勾选</option><option value="false">不勾选</option></select>:field.multiple&&field.options.length?<div className="option-checklist">{field.options.map(option=><label key={option}><input type="checkbox" checked={split(answers[action.selector]||'').includes(option)} onChange={e=>answerMulti(action,option,e.target.checked)}/>{option}</label>)}</div>:field.options.length?<select value={answers[action.selector]||''} onChange={e=>answer(action,e.target.value)}><option value="">暂不填写</option>{field.options.map(option=><option value={option} key={option}>{option}</option>)}</select>:<input value={answers[action.selector]||''} onChange={e=>answer(action,e.target.value)} placeholder="输入后会标记为用户明确确认"/>}{field.field_type!=='section-button'&&!action.sensitive&&answers[action.selector]&&<button type="button" className="remember-answer" disabled={!!busy} onClick={()=>remember(action)}><Save size={13}/>同步主档案</button>}</div></div>})}</div>:<div className="success-empty compact"><ShieldCheck size={25}/><h3>没有需要人工确认的问题</h3></div>}</section>}
    <section className={`card ${!plan?'disabled-card':''}`}><div className="execute-card"><div><SectionTitle n="05" title="填写、回读与提交前检查" sub="执行后重新读取网页值，并检查附件、人工确认项和页面错误"/>{execution&&<p className="execution-result"><Check size={15}/>{execution.verified} 项回读验证 · {execution.skipped} 项跳过 · {execution.failed} 项失败</p>}</div><div className="execute-actions">{plan&&<button className="secondary" disabled={!!busy} onClick={recheck}><RefreshCw size={15}/>{check?'重新检查':'检查当前页'}</button>}{workflow?.safe_next_present&&check&&<button className="primary" disabled={!overallReady||!!busy} onClick={continueStep}>{busy==='continuing'?<LoaderCircle className="spin" size={16}/>:<ExternalLink size={16}/>}检查通过，进入“{workflow.safe_next_label}”</button>}<button className="primary" disabled={!plan||(!readyCount&&!selectedResume)||!!busy} onClick={execute}>{busy==='filling'?<LoaderCircle className="spin" size={17}/>:<Play size={17}/>}填写并验证 {readyCount} 个字段</button></div></div>{check&&<div className={`preflight ${overallReady?'ready':'pending'}`}><div><ShieldCheck size={21}/><span><strong>{overallReady?'表单已具备人工终审条件':'还不能进入最终提交'}</strong><small>已填写 {check.filled_count} 项 · 必填项 {check.required_total} 个 · 待确认 {unresolvedGroups.length} 项 · 附件 {check.file_uploads.length} 个</small></span></div>{check.file_uploads.length>0&&<p>已上传：{check.file_uploads.join('、')}</p>}{unresolvedGroups.length>0&&<div><strong>等待你确认</strong><ul>{unresolvedGroups.map(group=><li key={group.key}>{group.label}</li>)}</ul></div>}{check.required_missing.length>0&&<div><strong>网页仍缺少</strong><ul>{check.required_missing.map((item,i)=><li key={`${item.selector}-${i}`}>{item.label||item.field_type}</li>)}</ul></div>}{execution&&execution.failed>0&&<div><strong>填写或回读失败</strong><ul>{execution.results.filter(item=>item.status==='failed'||!item.verified&&item.status==='filled').map((item,i)=><li key={`${item.selector}-failed-${i}`}>{item.label}：{item.message}</li>)}</ul></div>}{check.validation_errors.length>0&&<div><strong>页面校验提示</strong><ul>{check.validation_errors.map((item,i)=><li key={i}>{item}</li>)}</ul></div>}{check.human_challenges.length>0&&<div><strong>需要你手动完成</strong><ul>{check.human_challenges.map((item,i)=><li key={i}>{item}</li>)}</ul></div>}<footer><AlertTriangle size={14}/>当前阶段不会点击“{check.submit_labels[0]||'提交申请'}”。</footer></div>}</section>
  </div>
}

const workflowStageLabel=(stage:ApplicationWorkflowState['stage'])=>({job_detail:'职位详情',registration_required:'创建账号',auth_required:'需要登录',verification_required:'等待验证',profile_form:'在线简历',application_form:'申请表单',review:'提交前复核',unknown:'待识别'}[stage])
function WorkflowJourney({stage}:{stage:ApplicationWorkflowState['stage']}){const steps=['确认岗位','注册/登录','身份验证','填写申请','人工终审'];const index=stage==='job_detail'?0:stage==='registration_required'||stage==='auth_required'?1:stage==='verification_required'?2:stage==='profile_form'||stage==='application_form'?3:stage==='review'?4:0;return <div className="workflow-journey">{steps.map((label,i)=><div className={i<index?'done':i===index?'current':''} key={label}><span>{i<index?<Check size={12}/>:i+1}</span><small>{label}</small></div>)}</div>}
const comparisonStatusLabel=(status:FieldComparison['status'])=>({matched:'一致',missing:'网站漏填',conflict:'识别冲突',manual_review:'人工核对',unmapped:'缺少资料',option_unavailable:'选项不匹配'}[status])
const controlKind=(field:PageField)=>field.field_type==='section-button'?'需要先展开':field.field_type==='radio'?'单选组':field.field_type==='checkbox'?'勾选框':field.field_type==='select-multiple'||field.multiple?'下拉多选':field.field_type==='select-one'||field.field_type==='combobox'?'下拉单选':field.field_type==='textarea'?'长文本':'文本输入'

function SectionTitle({n,title,sub}:{n:string;title:string;sub:string}){return <div className="section-title"><span>{n}</span><div><h2>{title}</h2><p>{sub}</p></div></div>}
function Input({label,value,set,type='text'}:{label:string;value:string|number|null;set:(v:string)=>void;type?:string}){return <label className="field"><span>{label}</span><input type={type} value={value??''} onChange={e=>set(e.target.value)}/></label>}
function Select({label,value,values,set}:{label:string;value:string;values:string[];set:(v:string)=>void}){return <label className="field"><span>{label}</span><select value={value} onChange={e=>set(e.target.value)}>{values.map(v=><option key={v}>{v}</option>)}</select></label>}
function Text({label,value,set}:{label:string;value:string;set:(v:string)=>void}){return <label className="field text"><span>{label}</span><textarea value={value} onChange={e=>set(e.target.value)}/></label>}
function EditableList<T>({title,n,items,empty,set,render}:{title:string;n:string;items:T[];empty:T;set:(v:T[])=>void;render:(x:T,i:number,edit:(i:number,p:Partial<T>)=>void)=>React.ReactNode}){const edit=(i:number,p:Partial<T>)=>{const next=[...items];next[i]={...next[i],...p};set(next)};return <section className="card"><SectionTitle n={n} title={title} sub={`共 ${items.length} 条，可手动补充和修正`}/>{items.map((x,i)=><div className="list-item" key={i}><div className="list-head"><strong>{title} {i+1}</strong><button onClick={()=>set(items.filter((_,j)=>i!==j))}>移除</button></div>{render(x,i,edit)}</div>)}<button className="add" onClick={()=>set([...items,{...empty}])}><Plus size={16}/>添加一条</button></section>}
const split=(v:string)=>v.split(/[,，、]/).map(x=>x.trim()).filter(Boolean);const message=(e:unknown)=>e instanceof Error?e.message:'操作失败';const display=(v:unknown)=>typeof v==='string'?v:JSON.stringify(v);const formatBytes=(n:number)=>n?`${(n/1024).toFixed(n>1024*1024?0:1)} ${n>1024*1024?'MB':'KB'}`:'—'
